  1	import java.util.ArrayDeque;
  2	import java.util.ArrayList;
  3	import java.util.Arrays;
  4	import java.util.List;
  5	import java.util.Queue;
  6	
  7	class BipartiteGraph {
  8	    private static final int EDGE_ENDPOINT_COUNT = 2;
  9	    private static final int SOURCE_VERTEX_INDEX = 0;
 10	    private static final int TARGET_VERTEX_INDEX = 1;
 11	
 12	    @Deprecated
 13	    static ArrayList<ArrayList<Integer>> constructadj(int vertexCount, int[][] edges) {
 14	        return constructAdjacencyList(vertexCount, edges);
 15	    }
 16	
 17	    static ArrayList<ArrayList<Integer>> constructAdjacencyList(int vertexCount, int[][] edges) {
 18	        return Graph.fromEdges(vertexCount, edges).toAdjacencyList();
 19	    }
 20	
 21	    static boolean isBipartite(int vertexCount, int[][] edges) {
 22	        Graph graph = Graph.fromEdges(vertexCount, edges);
 23	
 24	        Color[] colors = new Color[graph.vertexCount()];
 25	        Arrays.fill(colors, Color.UNCOLORED);
 26	
 27	        for (int vertex = 0; vertex < graph.vertexCount(); vertex++) {
 28	            if (colors[vertex] == Color.UNCOLORED && !colorComponent(vertex, graph, colors)) {
 29	                return false;
 30	            }
 31	        }
 32	
 33	        return true;
 34	    }
 35	
 36	    private static boolean colorComponent(
 37	            int startVertex,
 38	            Graph graph,
 39	            Color[] colors
 40	    ) {
 41	        Queue<Integer> queue = new ArrayDeque<>();
 42	        colors[startVertex] = Color.FIRST;
 43	        queue.offer(startVertex);
 44	
 45	        while (!queue.isEmpty()) {
 46	            int currentVertex = queue.poll();
 47	
 48	            for (int neighbor : graph.neighborsOf(currentVertex)) {
 49	                if (colors[neighbor] == Color.UNCOLORED) {
 50	                    colors[neighbor] = colors[currentVertex].opposite();
 51	                    queue.offer(neighbor);
 52	                } else if (colors[neighbor] == colors[currentVertex]) {
 53	                    return false;
 54	                }
 55	            }
 56	        }
 57	
 58	        return true;
 59	    }
 60	
 61	    private static ArrayList<ArrayList<Integer>> createEmptyAdjacencyList(int vertexCount) {
 62	        ArrayList<ArrayList<Integer>> adjacencyList = new ArrayList<>();
 63	
 64	        for (int vertex = 0; vertex < vertexCount; vertex++) {
 65	            adjacencyList.add(new ArrayList<>());
 66	        }
 67	
 68	        return adjacencyList;
 69	    }
 70	
 71	    private static void addUndirectedEdge(
 72	            ArrayList<ArrayList<Integer>> adjacencyList,
 73	            int sourceVertex,
 74	            int targetVertex
 75	    ) {
 76	        adjacencyList.get(sourceVertex).add(targetVertex);
 77	        adjacencyList.get(targetVertex).add(sourceVertex);
 78	    }
 79	
 80	    private static void validateInput(int vertexCount, int[][] edges) {
 81	        if (vertexCount < 0) {
 82	            throw new IllegalArgumentException("vertexCount must be non-negative");
 83	        }
 84	
 85	        if (edges == null) {
 86	            throw new IllegalArgumentException("edges must not be null");
 87	        }
 88	
 89	        for (int edgeIndex = 0; edgeIndex < edges.length; edgeIndex++) {
 90	            validateEdge(edges[edgeIndex], edgeIndex, vertexCount);
 91	        }
 92	    }
 93	
 94	    private static void validateEdge(int[] edge, int edgeIndex, int vertexCount) {
 95	        if (edge == null || edge.length != EDGE_ENDPOINT_COUNT) {
 96	            throw new IllegalArgumentException(
 97	                    "edge at index " + edgeIndex + " must contain exactly two vertices"
 98	            );
 99	        }
100	
101	        validateVertex(edge[SOURCE_VERTEX_INDEX], edgeIndex, vertexCount);
102	        validateVertex(edge[TARGET_VERTEX_INDEX], edgeIndex, vertexCount);
103	    }
104	
105	    private static void validateVertex(int vertex, int edgeIndex, int vertexCount) {
106	        if (vertex < 0 || vertex >= vertexCount) {
107	            throw new IllegalArgumentException(
108	                    "edge at index " + edgeIndex + " references invalid vertex " + vertex
109	            );
110	        }
111	    }
112	
113	    public static void main(String[] args) {
114	        int vertexCount = 4;
115	
116	        int[][] edges = {{0, 1}, {0, 2}, {1, 2}, {2, 3}};
117	
118	        System.out.println(isBipartite(vertexCount, edges));
119	    }
120	
121	    private static final class Graph {
122	        private final ArrayList<ArrayList<Integer>> adjacencyList;
123	
124	        private Graph(ArrayList<ArrayList<Integer>> adjacencyList) {
125	            this.adjacencyList = adjacencyList;
126	        }
127	
128	        private static Graph fromEdges(int vertexCount, int[][] edges) {
129	            validateInput(vertexCount, edges);
130	
131	            ArrayList<ArrayList<Integer>> adjacencyList = createEmptyAdjacencyList(vertexCount);
132	
133	            for (int[] edge : edges) {
134	                addUndirectedEdge(
135	                        adjacencyList,
136	                        edge[SOURCE_VERTEX_INDEX],
137	                        edge[TARGET_VERTEX_INDEX]
138	                );
139	            }
140	
141	            return new Graph(adjacencyList);
142	        }
143	
144	        private int vertexCount() {
145	            return adjacencyList.size();
146	        }
147	
148	        private List<Integer> neighborsOf(int vertex) {
149	            return adjacencyList.get(vertex);
150	        }
151	
152	        private ArrayList<ArrayList<Integer>> toAdjacencyList() {
153	            return adjacencyList;
154	        }
155	    }
156	
157	    private enum Color {
158	        UNCOLORED,
159	        FIRST,
160	        SECOND;
161	
162	        private Color opposite() {
163	            if (this == FIRST) {
164	                return SECOND;
165	            }
166	
167	            if (this == SECOND) {
168	                return FIRST;
169	            }
170	
171	            throw new IllegalStateException("Uncolored vertices do not have an opposite color");
172	        }
173	    }
174	}
